import pty,os,fcntl,termios,struct,re
def run(cols, args, cwd, rows=40, exe="/workspace/executable", env=None):
    pid, fd = pty.fork()
    if pid == 0:
        e=dict(os.environ)
        if env: e.update(env)
        os.chdir(cwd); os.execve(exe, [exe]+args, e)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0, 0))
    out=b""
    while True:
        try: d=os.read(fd,65536)
        except OSError: break
        if not d: break
        out+=d
    os.waitpid(pid,0)
    return out.decode(errors='replace')
def parse(o):
    res=[]
    for l in o.splitlines():
        m=re.match(r'^(.*?)\u2502( *)(\S*)\u2502(.*?)(\d+)%(\s+)(.*)$',l)
        if m:
            res.append(dict(name=len(m.group(1)),lead=len(m.group(2)),bar=len(m.group(3)),tail=m.group(4),pct=m.group(5),size=m.group(7),raw=l))
        elif l.strip():
            res.append(dict(hdr=l))
    return res
EOF
