```rust
pub fn parse<C: IntoIterator>(&self, args: C) -> Result<Matches> {
    let opts: Vec<Opt> = self.grps.iter().map(|x| x.clone()).collect();

    let mut vals = (0..opts.len()).map(|_| Vec::new()).collect::<Vec<Vec<(usize, Optval)>>>();
    let mut free: Vec<String> = Vec::new();
    let args = args.into_iter().map(...).collect::<Vec<_>>();
    let mut args = args.into_iter().peekable();
    let mut arg_pos = 0;
    while let Some(cur) = args.next() {
        if !is_arg(&cur) {
            free.push(cur);
        } else if cur == "--" {
            free.extend(args);
            break;
        } else {
            let mut names;
            let mut i_arg = None;
            let mut was_long = true;
            if cur.as_bytes()[1] == b'-' || self.long_only {
                let tail = if cur.starts_with("--") { &cur[2..] } else { &cur[1..] };
                let mut parts = tail.splitn(2, '=');
                names = vec![Name::from_str(parts.next().unwrap())];
                if let Some(rest) = parts.next() {
                    i_arg = Some(rest.to_string());
                }
            } else {
                was_long = false;
                names = Vec::new();
                for (j, ch) in cur.char_indices().skip(1) {
                    let opt = ShortOpt { short_name: ch, hasarg: No, ... };
                    let opt_id = match find_opt(&opts, &Name::Short(ch)) {
                        Some(id) => id,
                        None => return Err(UnrecognizedOption(ch.to_string())),
                    };

                    names.push(Name::Short(ch));

                    let arg_follow = match opts[opt_id].hasarg {
                        Yes | Maybe => true,
                        No => false,
                    };
                    if arg_follow {
                        // There is an argument to this option
                        let next = j + ch.len_utf8();
                        if next < cur.len() {
                            i_arg = Some(cur[next..].to_string());
                        }
                        break;
                    }
                }
            }
            let mut name_pos = 0;
            for nm in names.iter() {
                name_pos += 1;
                let optid = match find_opt(&opts, nm) {
                    Some(id) => id,
                    None => return Err(UnrecognizedOption(nm.to_string())),
                };
                match opts[optid].hasarg {
                    No => {
                        if name_pos == names.len() && i_arg.is_some() {
                            return Err(UnexpectedArgument(nm.to_string()));
                        }
                        vals[optid].push((arg_pos, Val(String::new())));
                    }
                    Maybe => {
                        // Note that here you cannot simply do `i_arg.take()`. Since
                        // `name_pos` is not advanced beyond the current value, if
                        // the option is specified multiple times in one argument
                        // (e.g. `-vvvv`), the `i_arg` will be duplicated.
                        let mut val = i_arg.take();
                        if val.is_none() {
                            if opts[optid].occurr == Required {
                                ...
                            }
                            // Value of this option is optional. If the next argument
                            // is not an option, then this argument is the value of
                            // this option.
                            if let Some(n) = args.peek() {
                                if !is_arg(n) {
                                    val = Some(args.next().unwrap());
                                }
                            }
                        }
                        ...
                    }
                    Yes => { ... }
                }
            }
        }
    }
}
```

