```rust
fn usage_items<'a>(&'a self) -> Box<dyn Iterator<Item = String> + 'a> {
    let desc_sep = format!("\n{}", " ".repeat(24));

    let rows = self.grps.iter().map(move |optref| {
        let Opt { hasarg, occurr, hint, short_name, long_name, desc, .. } = (*optref).clone();

        let mut row = "    ".to_string();

        // short option
        match short_name {
            Some(short) => {
                row.push('-');
                row.push(short);
                if long_name.is_some() {
                    row.push_str(", ");
                } else {
                    // Only a single space here, so that any
                    // description is aligned with those that
                    // print both short and long.
                    row.push(' ');
                }
            }
            None => {
                row.push_str("    ");
            }
        }

        // long option
        match long_name {
            Some(long) => {
                row.push_str("--");
                row.push_str(long);
            }
            None => {}
        }

        // arg
        match hasarg {
            No => {}
            Yes => row.push_str(" " + &hint),
            Maybe => row.push_str(&format!(" [{}]", hint)),
        }

        let rowlen = row.chars().count();
        if rowlen < 24 {
            for _ in 0..24 - rowlen {
                row.push(' ');
            }
        } else {
            row.push_str(&desc_sep)
        }

        // Normalize desc to contain words separated by one space character
        let desc_normalizer = desc.split_whitespace();
        let mut desc_words = desc_normalizer.collect::<VecDeque<String>>();

        let mut row = {
            let mut row = row;
            loop {
                let word = match desc_words.pop_front() {
                    Some(word) => word,
                    None => break,
                };

                let word_len = word.chars().count();
                let row_len = row.chars().count();
                if row_len + 1 + word_len > 78 {
                    row.push_str(&desc_sep);
                    row.push_str(&word);
                } else {
                    if row_len != 0 {
                        row.push(' ');
                    }
                    row.push_str(&word);
                }
            }
            row
        };
        row
    });
    ...
}
```

