import pty,os,fcntl,termios,struct
def run(cols, args, cwd='/tmp/z3'):
    pid, fd = pty.fork()
    if pid == 0:
        os.chdir(cwd); os.execv("/workspace/executable", ["/workspace/executable"]+args)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", 40, cols, 0, 0))
    out=b""
    while True:
        try: d=os.read(fd,65536)
        except OSError: break
        if not d: break
        out+=d
    os.waitpid(pid,0)
    return out.decode(errors='replace')
for cols in (14,15,20,46,47,80):
    o=run(cols,['-A','.'],'/tmp/z3')
    lines=o.splitlines()
    print("cols=%-3d nlines=%-3d %r" % (cols, len(lines), lines[1][:60] if len(lines)>1 else ''))
EOF

