// ---------------------------------------------------------------- size formatting

const UNITS: [&str; 7] = ["B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB"];

fn fmt_size(bytes: u64, bytes_mode: bool) -> String {
    if bytes_mode {
        return format!("{} B", bytes);
    }
    let mut v = bytes as f64;
    let mut i = 0usize;
    while v >= 1024.0 && i + 1 < UNITS.len() {
        v /= 1024.0;
        i += 1;
    }
    if i == 0 {
        format!("{} B", bytes)
    } else {
        format!("{:.2} {}", v, UNITS[i])
    }
}

// ---------------------------------------------------------------- LS_COLORS

pub struct Colors {
    types: HashMap<String, String>,
    exts: HashMap<String, String>,
}

impl Colors {
    fn get(&self, k: &str) -> Option<&String> {
        self.types.get(k)
    }
    fn ext(&self, e: &str) -> Option<&String> {
        self.exts.get(e)
    }
    fn empty(&self) -> bool {
        self.types.is_empty() && self.exts.is_empty()
    }
}

fn parse_ls_colors(s: &str) -> Colors {
    let mut types: HashMap<String, String> = HashMap::new();
    let mut exts: HashMap<String, String> = HashMap::new();
    for entry in s.split(':') {
        if entry.is_empty() {
            continue;
        }
        let mut it = entry.split('=');
        let key = it.next().unwrap();
        let val = it.next().unwrap();
        let (a, b) = key.split_at(2);
        if a == "*." {
            exts.insert(b.to_string(), val.to_string());
        } else {
            types.insert(key.to_string(), val.to_string());
        }
    }
    Colors { types, exts }
}

// ---------------------------------------------------------------- option parsing (getopts compatible)

#[derive(Clone, Copy, PartialEq)]
enum HasArg {
    No,
    Yes,
    Maybe,
}

#[derive(Clone, Copy, PartialEq)]
enum Occur {
    Optional,
    Multi,
}

struct OptDef {
    short: Option<char>,
    long: Option<&'static str>,
    hasarg: HasArg,
    occur: Occur,
    hint: &'static str,
    desc: &'static str,
}

impl OptDef {
    fn name(&self) -> String {
        match self.long {
            Some(l) => l.to_string(),
            None => self.short.unwrap().to_string(),
        }
    }
}

fn opt_defs() -> Vec<OptDef> {
    vec![
        OptDef { short: Some('d'), long: Some("depth"), hasarg: HasArg::Maybe, occur: Occur::Optional, hint: "[DEPTH]", desc: "show directories up to depth N (def 1)" },
        OptDef { short: Some('a'), long: Some("aggr"), hasarg: HasArg::Maybe, occur: Occur::Optional, hint: "[N[KMG]]", desc: "aggregate smaller than N B/KiB/MiB/GiB (def 1M)" },
        OptDef { short: Some('s'), long: Some("summary"), hasarg: HasArg::No, occur: Occur::Optional, hint: "", desc: "equivalent to -da, or -d1 -a1M" },
        OptDef { short: Some('u'), long: Some("usage"), hasarg: HasArg::No, occur: Occur::Optional, hint: "", desc: "report real disk usage instead of file size" },
        OptDef { short: Some('b'), long: Some("bytes"), hasarg: HasArg::No, occur: Occur::Optional, hint: "", desc: "print sizes in bytes" },
        OptDef { short: Some('f'), long: Some("files-only"), hasarg: HasArg::No, occur: Occur::Optional, hint: "", desc: "skip directories for a fast local overview" },
        OptDef { short: Some('x'), long: Some("exclude"), hasarg: HasArg::Yes, occur: Occur::Multi, hint: "NAME", desc: "exclude matching files or directories" },
        OptDef { short: Some('H'), long: Some("no-hidden"), hasarg: HasArg::No, occur: Occur::Optional, hint: "", desc: "exclude hidden files" },
        OptDef { short: Some('A'), long: Some("ascii"), hasarg: HasArg::No, occur: Occur::Optional, hint: "", desc: "ASCII characters only, no colors" },
        OptDef { short: Some('h'), long: Some("help"), hasarg: HasArg::No, occur: Occur::Optional, hint: "", desc: "show help" },
        OptDef { short: Some('v'), long: Some("version"), hasarg: HasArg::No, occur: Occur::Optional, hint: "", desc: "print version number" },
    ]
}

struct Matches {
    vals: Vec<Vec<Option<String>>>,
    free: Vec<String>,
}

impl Matches {
    fn opt_str(&self, idx: usize) -> Option<&String> {
        match self.vals[idx].last() {
            Some(Some(v)) => Some(v),
            Some(None) => None,
            None => None,
        }
    }
    fn opt_present(&self, idx: usize) -> bool {
        !self.vals[idx].is_empty()
    }
    fn opt_strs(&self, idx: usize) -> Vec<String> {
        self.vals[idx]
            .iter()
            .filter_map(|v| v.as_ref().cloned())
            .collect()
    }
}

fn is_arg(s: &str) -> bool {
    s.len() > 1 && s.as_bytes()[0] == b'-'
}

fn parse_args(defs: &[OptDef], args: &[String]) -> Result<Matches, String> {
    let mut vals: Vec<Vec<Option<String>>> = vec![Vec::new(); defs.len()];
    let mut free: Vec<String> = Vec::new();
    let mut i = 0usize;
    while i < args.len() {
        let cur = &args[i];
        i += 1;
        if !is_arg(cur) {
            free.push(cur.clone());
            continue;
        }
        if cur == "--" {
            free.extend(args[i..].iter().cloned());
            break;
        }
        let mut names: Vec<usize> = Vec::new();
        let mut i_arg: Option<String> = None;
        let mut was_long = true;
        if cur.as_bytes()[1] == b'-' {
            let tail = &cur[2..];
            let mut parts = tail.splitn(2, '=');
            let nm = parts.next().unwrap();
            if let Some(rest) = parts.next() {
                i_arg = Some(rest.to_string());
            }
            match find_opt(defs, nm) {
                Some(idx) => names.push(idx),
                None => return Err(format!("Unrecognized option: '{}'", nm)),
            }
        } else {
            was_long = false;
            let chars: Vec<(usize, char)> = cur.char_indices().skip(1).collect();
            let mut stop = false;
            for (j, ch) in chars {
                let idx = match find_opt(defs, &ch.to_string()) {
                    Some(idx) => idx,
                    None => return Err(format!("Unrecognized option: '{}'", ch)),
                };
                names.push(idx);
                if defs[idx].hasarg != HasArg::No {
                    let next = j + ch.len_utf8();
                    if next < cur.len() {
                        i_arg = Some(cur[next..].to_string());
                    }
                    stop = true;
                }
                if stop {
                    break;
                }
            }
        }
        let n = names.len();
        for (pos, idx) in names.iter().enumerate() {
            match defs[*idx].hasarg {
                HasArg::No => {
                    if pos + 1 == n && i_arg.is_some() {
                        return Err(format!("Option '{}' does not take an argument", defs[*idx].name()));
                    }
                    vals[*idx].push(None);
                }
                HasArg::Maybe => {
                    let mut val = i_arg.take();
                    if val.is_none() && !was_long {
                        if i < args.len() && !is_arg(&args[i]) {
                            val = Some(args[i].clone());
                            i += 1;
                        }
                    }
                    vals[*idx].push(val);
                }
                HasArg::Yes => {
                    let val = match i_arg.take() {
                        Some(v) => v,
                        None => {
                            if i < args.len() {
                                let v = args[i].clone();
                                i += 1;
                                v
                            } else {
                                return Err(format!("Argument to option '{}' missing", defs[*idx].name()));
                            }
                        }
                    };
                    vals[*idx].push(Some(val));
                }
            }
        }
    }
    for (idx, d) in defs.iter().enumerate() {
        if d.occur == Occur::Optional && vals[idx].len() > 1 {
            return Err(format!("Option '{}' given more than once", d.name()));
        }
    }
    Ok(Matches { vals, free })
}

fn find_opt(defs: &[OptDef], name: &str) -> Option<usize> {
    if name.len() == 1 {
        let c = name.chars().next().unwrap();
        defs.iter().position(|d| d.short == Some(c))
    } else {
        defs.iter().position(|d| d.long == Some(name))
    }
}

fn usage(prog: &str) -> String {
    let brief = format!("Usage: {} [options] <path> [<path>..]", prog);
    let mut out = format!("{}\n\nOptions:\n", brief);
    for d in opt_defs().iter() {
        let mut row = String::from("    ");
        match d.short {
            Some(s) => {
                row.push('-');
                row.push(s);
                if d.long.is_some() {
                    row.push_str(", ");
                } else {
                    row.push(' ');
                }
            }
            None => {
                row.push_str("    ");
            }
        }
        if let Some(l) = d.long {
            row.push_str("--");
            row.push_str(l);
        }
        match d.hasarg {
            HasArg::No => {}
            HasArg::Yes => row.push_str(&format!(" {}", d.hint)),
            HasArg::Maybe => row.push_str(&format!(" [{}]", d.hint)),
        }
        let rowlen = row.chars().count();
        if rowlen < 24 {
            for _ in 0..24 - rowlen {
                row.push(' ');
            }
        } else {
            row.push_str("\n");
            row.push_str(&" ".repeat(24));
        }
        let desc_sep = format!("\n{}", " ".repeat(24));
        for word in d.desc.split_whitespace() {
            let wl = word.chars().count();
            let rl = row.chars().count();
            if rl + 1 + wl > 78 {
                row.push_str(&desc_sep);
                row.push_str(word);
            } else {
                if rl != 0 {
                    row.push(' ');
                }
                row.push_str(word);
            }
        }
        out.push_str(&row);
        out.push('\n');
    }
    out
}

// ---------------------------------------------------------------- terminal width

extern "C" {
    fn ioctl(fd: i32, request: u64, ...) -> i32;
}

#[repr(C)]
struct Winsize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

fn term_width() -> usize {
    let mut ws = Winsize { ws_row: 0, ws_col: 0, ws_xpixel: 0, ws_ypixel: 0 };
    let rc = unsafe { ioctl(1, 0x5413u64, &mut ws as *mut Winsize) };
    if rc == 0 && ws.ws_col > 0 {
        ws.ws_col as usize
    } else {
        80
    }
}

// ---------------------------------------------------------------- tree

#[derive(Clone, Copy, PartialEq)]
enum Kind {
    Dir,
    File,
    Link,
    Other,
}

struct Node {
    name: String,
    own: u64,
    total: u64,
    kind: Kind,
    link_ok: bool,
    exec: bool,
    ext: Option<String>,
    children: Vec<Node>,
    bar: usize,
    aggregated: bool,
}

impl Node {
    fn new(name: String, own: u64, kind: Kind) -> Node {
        Node {
            name,
            own,
            total: own,
            kind,
            link_ok: false,
            exec: false,
            ext: None,
            children: Vec::new(),
            bar: 0,
            aggregated: false,
        }
    }
}

struct Opts {
    depth: usize,
    aggr: u64,
    usage: bool,
    bytes: bool,
    files_only: bool,
    excludes: Vec<String>,
    no_hidden: bool,
    ascii: bool,
    colors: Colors,
    use_colors: bool,
}

fn list_dir(path: &Path, name: &str) -> Vec<fs::DirEntry> {
    match fs::read_dir(path) {
        Ok(rd) => rd.filter_map(|e| e.ok()).collect(),
        Err(e) => {
            eprintln!("Couldn't read {} ({:?})", name, e.kind());
            Vec::new()
        }
    }
}

fn scan(path: &Path, name: &str, depth: usize, o: &Opts, root: bool) -> Node {
    let md = fs::symlink_metadata(path);
    let (own, kind, exec, ext) = match md {
        Ok(m) => {
            let sz = if o.usage { m.blocks().saturating_mul(512) } else { m.len() };
            let ft = m.file_type();
            let k = if ft.is_dir() {
                Kind::Dir
            } else if ft.is_symlink() {
                Kind::Link
            } else if ft.is_file() {
                Kind::File
            } else {
                Kind::Other
            };
            let ex = m.mode() & 0o111 != 0;
            let ext = Path::new(name).extension().map(|e| e.to_string_lossy().to_string());
            (sz, k, ex, ext)
        }
        Err(_) => (0, Kind::File, false, None),
    };
    let mut node = Node::new(name.to_string(), own, kind);
    node.exec = exec;
    node.ext = ext;
    if kind == Kind::Link {
        node.link_ok = fs::metadata(path).is_ok();
    }
    if kind != Kind::Dir || o.files_only {
        if root && kind == Kind::Dir {
            // files-only root directory: no children
        }
        return node;
    }
    let entries = list_dir(path, name);
    if depth < o.depth {
        let _ = list_dir(path, name);
    }
    let mut children: Vec<Node> = Vec::new();
    for e in entries {
        let cname = e.file_name().to_string_lossy().to_string();
        if o.no_hidden && cname.starts_with('.') {
            continue;
        }
        if o.excludes.iter().any(|x| x == &cname) {
            continue;
        }
        let cpath = path.join(&cname);
        let child = scan(&cpath, &cname, depth + 1, o, false);
        children.push(child);
    }
    node.children = children;
    node.total = node.own + node.children.iter().map(|c| c.total).sum::<u64>();
    node
}

fn aggregate(node: &mut Node, o: &Opts) {
    if !node.children.is_empty() {
        for c in node.children.iter_mut() {
            aggregate(c, o);
        }
        let mut shown: Vec<Node> = Vec::new();
        let mut small: Vec<Node> = Vec::new();
        for c in node.children.drain(..) {
            if c.total < o.aggr {
                small.push(c);
            } else {
                shown.push(c);
            }
        }
        let sum: u64 = small.iter().map(|c| c.total).sum();
        shown.sort_by(|a, b| b.total.cmp(&a.total));
        if sum > 0 {
            let mut n = Node::new("<aggregated>".to_string(), sum, Kind::File);
            n.total = sum;
            n.aggregated = true;
            shown.push(n);
        }
        node.children = shown;
    }
}

fn assign_bars(node: &mut Node, parent_bar: usize, denom: u64) {
    if node.children.is_empty() {
        return;
    }
    for c in node.children.iter_mut() {
        let w = (c.total * parent_bar as u64) / denom;
        c.bar = if w == 0 { 0 } else { (w - 1) as usize };
    }
    for c in node.children.iter_mut() {
        assign_bars(c, c.bar, c.total.max(1));
    }
}

// ---------------------------------------------------------------- printing

fn fit(name: &str, avail: usize) -> (String, usize) {
    let mut w = 0usize;
    let mut out = String::new();
    for c in name.chars() {
        let cw = char_width(c);
        if w + cw > avail {
            return (out, avail);
        }
        out.push(c);
        w += cw;
    }
    (out, w)
}

fn bar_string(bars: &[usize], w: usize, fill: char, shades: &[char], ascii: bool) -> String {
    let mut s = String::new();
    let mut prev = 0usize;
    let d = bars.len();
    for (i, &b) in bars.iter().enumerate() {
        let start = w - b;
        if i + 1 < d {
            let shade = if ascii { '#' } else { shades[i] };
            s.push_str(&shade.to_string().repeat(start - prev));
        } else {
            if i > 0 {
                let shade = if ascii { '#' } else { shades[i - 1] };
                s.push_str(&shade.to_string().repeat(start - prev));
            } else {
                s.push_str(&" ".repeat(start - prev));
            }
            s.push_str(&fill.to_string().repeat(w - start));
        }
        prev = start;
    }
    s
}

fn color_for(node: &Node, colors: &Colors) -> Option<String> {
    if node.kind == Kind::Dir {
        return colors.get("di").cloned();
    }
    if node.kind == Kind::Link {
        if node.link_ok {
            return colors.get("ln").cloned();
        } else {
            return colors.get("or").cloned();
        }
    }
    if node.exec {
        return colors.get("ex").cloned();
    }
    if let Some(e) = &node.ext {
        if let Some(c) = colors.ext(e) {
            return Some(c.clone());
        }
    }
    if node.kind == Kind::File {
        return colors.get("fi").cloned();
    }
    colors.get("bd").cloned()
}

fn print_node(
    node: &Node,
    prefix: &str,
    ancestors: &[usize],
    name_w: usize,
    bar_w: usize,
    o: &Opts,
    parent_total: u64,
) {
    let prefix_w = str_width(prefix);
    if prefix_w >= name_w {
        return;
    }
    let avail = name_w - 1 - prefix_w;
    let (disp, dw) = fit(&node.name, avail);
    let pad = name_w - prefix_w - dw;
    let mut line = String::new();
    line.push_str(prefix);
    match color_for(node, &o.colors) {
        Some(c) if o.use_colors => {
            line.push_str(&format!("\x1b[{}m{}\x1b[0m", c, disp));
        }
        _ => line.push_str(&disp),
    }
    for _ in 0..pad {
        line.push(' ');
    }
    line.push('\u{2502}');
    line.push(' ');
    let mut bars: Vec<usize> = ancestors.to_vec();
    bars.push(node.bar);
    let fill = if o.ascii { '#' } else { '\u{2588}' };
    let shades = ['\u{2591}', '\u{2592}', '\u{2593}', '\u{2588}'];
    line.push_str(&bar_string(&bars, bar_w, fill, &shades, o.ascii));
    line.push('\u{2502}');
    let pct = (node.total * 100 / parent_total) as usize;
    line.push_str(&format!("{:>4}%", pct));
    let st = fmt_size(node.total, o.bytes);
    let sw = st.chars().count().max(14);
    line.push_str(&format!("{:>width$}", st, width = sw));
    println!("{}", line);
    let mut child_prefix = String::from(prefix);
    if node.children.is_empty() {
        return;
    }
    let last = node.children.len() - 1;
    for (i, c) in node.children.iter().enumerate() {
        let conn = if i == last { "└─ " } else { "├─ " };
        let mut ap: Vec<usize> = ancestors.to_vec();
        ap.push(node.bar);
        print_node(c, &format!("{}{}", child_prefix, conn), &ap, name_w, bar_w, o, node.total);
    }
    if last == 0 {
        child_prefix.push_str("   ");
    } else {
        child_prefix.push_str("│  ");
    }
    let _ = child_prefix;
}

pub fn run() {
    let argv: Vec<String> = env::args().collect();
    let prog = argv.get(0).cloned().unwrap_or_else(|| "dutree".to_string());
    let defs = opt_defs();
    let matches = match parse_args(&defs, &argv[1..]) {
        Ok(m) => m,
        Err(e) => {
            print!("{}", usage(&prog));
            flush();
            eprintln!("{}", e);
            std::process::exit(1);
        }
    };
    if matches.opt_present(9) {
        print!("{}", usage(&prog));
        flush();
        return;
    }
    if matches.opt_present(10) {
        println!("{}", VERSION);
        return;
    }
    let mut paths = matches.free.clone();
    if paths.is_empty() {
        paths.push(".".to_string());
    }
    for p in &paths {
        if !fs::metadata(p).is_ok() {
            eprintln!("path {} doesn't exist", p);
            flush();
            std::process::exit(1);
        }
    }
    let depth = match matches.opt_str(0) {
        Some(s) => s.parse::<usize>().unwrap_or(usize::MAX),
        None => usize::MAX,
    };
    let aggr_str = match matches.opt_str(1) {
        Some(s) => s.clone(),
        None => "1M".to_string(),
    };
    if matches.opt_present(2) {
        // summary: -d 1 -a 1M
    }
    let summary = matches.opt_present(2);
    let depth = if summary { 1 } else { depth };
    let aggr = if summary { parse_size("1M") } else { 0 };
    let _ = aggr_str;
    println!("placeholder");
}

fn flush() {
    let _ = std::io::stdout().flush();
}

fn parse_size(s: &str) -> u64 {
    let (num, mult) = split_size(s);
    let _ = (num, mult);
    0
}

fn split_size(s: &str) -> (&str, u64) {
    (s, 1)
}
