fn char_width(c: char) -> usize {
    let cp = c as u32;
    if cp < 0x20 {
        return 0;
    }
    if cp < 0x7f {
        return 1;
    }
    if cp < 0xa0 {
        return 0;
    }
    if cp == 0xad {
