// ---------------------------------------------------------------- size formatting

const UNITS: [&str; 7] = ["B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB"];

fn fmt_size(bytes: u64, bytes_mode: bool) -> String {
    if bytes_mode {
        return format!("{} B", bytes);
    }
    let mut v = bytes as f64;
    let mut i = 0usize;
    while v >= 1024.0 && i + 1 < UNITS.len() {
        v /= 1024.0;
        i += 1;
    }
    if i == 0 {
        format!("{} B", bytes)
    } else {
        format!("{:.2} {}", v, UNITS[i])
    }
}

// ---------------------------------------------------------------- LS_COLORS

pub struct Colors {
    types: HashMap<String, String>,
    exts: HashMap<String, String>,
}

impl Colors {
    fn get(&self, k: &str) -> Option<&String> {
        self.types.get(k)
    }
    fn ext(&self, e: &str) -> Option<&String> {
        self.exts.get(e)
    }
    fn empty(&self) -> bool {
        self.types.is_empty() && self.exts.is_empty()
    }
}

fn parse_ls_colors(s: &str) -> Colors {
    let mut types: HashMap<String, String> = HashMap::new();
    let mut exts: HashMap<String, String> = HashMap::new();
    for entry in s.split(':') {
        if entry.is_empty() {
            continue;
        }
        let mut it = entry.split('=');
        let key = it.next().unwrap();
        let val = it.next().unwrap();
        let (a, b) = key.split_at(2);
        if a == "*." {
            exts.insert(b.to_string(), val.to_string());
        } else {
            types.insert(key.to_string(), val.to_string());
        }
    }
    Colors { types, exts }
}

// ---------------------------------------------------------------- option parsing (getopts compatible)

#[derive(Clone, Copy, PartialEq)]
enum HasArg {
    No,
    Yes,
    Maybe,
}

#[derive(Clone, Copy, PartialEq)]
enum Occur {
    Optional,
    Multi,
}

struct OptDef {
    short: Option<char>,
    long: Option<&'static str>,
    hasarg: HasArg,
    occur: Occur,
    hint: &'static str,
    desc: &'static str,
}

impl OptDef {
    fn name(&self) -> String {
        match self.long {
            Some(l) => l.to_string(),
            None => self.short.unwrap().to_string(),
        }
    }
}

fn opt_defs() -> Vec<OptDef> {
    vec![
        OptDef { short: Some('d'), long: Some("depth"), hasarg: HasArg::Maybe, occur: Occur::Optional, hint: "[DEPTH]", desc: "show directories up to depth N (def 1)" },
        OptDef { short: Some('a'), long: Some("aggr"), hasarg: HasArg::Maybe, occur: Occur::Optional, hint: "[N[KMG]]", desc: "aggregate smaller than N B/KiB/MiB/GiB (def 1M)" },
        OptDef { short: Some('s'), long: Some("summary"), hasarg: HasArg::No, occur: Occur::Optional, hint: "", desc: "equivalent to -da, or -d1 -a1M" },
        OptDef { short: Some('u'), long: Some("usage"), hasarg: HasArg::No, occur: Occur::Optional, hint: "", desc: "report real disk usage instead of file size" },
        OptDef { short: Some('b'), long: Some("bytes"), hasarg: HasArg::No, occur: Occur::Optional, hint: "", desc: "print sizes in bytes" },
        OptDef { short: Some('f'), long: Some("files-only"), hasarg: HasArg::No, occur: Occur::Optional, hint: "", desc: "skip directories for a fast local overview" },
        OptDef { short: Some('x'), long: Some("exclude"), hasarg: HasArg::Yes, occur: Occur::Multi, hint: "NAME", desc: "exclude matching files or directories" },
        OptDef { short: Some('H'), long: Some("no-hidden"), hasarg: HasArg::No, occur: Occur::Optional, hint: "", desc: "exclude hidden files" },
        OptDef { short: Some('A'), long: Some("ascii"), hasarg: HasArg::No, occur: Occur::Optional, hint: "", desc: "ASCII characters only, no colors" },
        OptDef { short: Some('h'), long: Some("help"), hasarg: HasArg::No, occur: Occur::Optional, hint: "", desc: "show help" },
        OptDef { short: Some('v'), long: Some("version"), hasarg: HasArg::No, occur: Occur::Optional, hint: "", desc: "print version number" },
    ]
}

struct Matches {
    vals: Vec<Vec<Option<String>>>,
    free: Vec<String>,
}

impl Matches {
    fn opt_str(&self, idx: usize) -> Option<&String> {
        match self.vals[idx].last() {
            Some(Some(v)) => Some(v),
            Some(None) => None,
            None => None,
        }
    }
    fn opt_present(&self, idx: usize) -> bool {
        !self.vals[idx].is_empty()
    }
    fn opt_strs(&self, idx: usize) -> Vec<String> {
        self.vals[idx]
            .iter()
            .filter_map(|v| v.as_ref().cloned())
            .collect()
    }
}

fn is_arg(s: &str) -> bool {
    s.len() > 1 && s.as_bytes()[0] == b'-'
}

fn parse_args(defs: &[OptDef], args: &[String]) -> Result<Matches, String> {
    let mut vals: Vec<Vec<Option<String>>> = vec![Vec::new(); defs.len()];
    let mut free: Vec<String> = Vec::new();
    let mut i = 0usize;
    while i < args.len() {
        let cur = &args[i];
        i += 1;
        if !is_arg(cur) {
            free.push(cur.clone());
            continue;
        }
        if cur == "--" {
            free.extend(args[i..].iter().cloned());
            break;
        }
        let mut names: Vec<usize> = Vec::new();
        let mut i_arg: Option<String> = None;
        let mut was_long = true;
        if cur.as_bytes()[1] == b'-' {
            let tail = &cur[2..];
            let mut parts = tail.splitn(2, '=');
            let nm = parts.next().unwrap();
            if let Some(rest) = parts.next() {
                i_arg = Some(rest.to_string());
            }
            match find_opt(defs, nm) {
                Some(idx) => names.push(idx),
                None => return Err(format!("Unrecognized option: '{}'", nm)),
            }
        } else {
            was_long = false;
            let chars: Vec<(usize, char)> = cur.char_indices().skip(1).collect();
            let mut stop = false;
            for (j, ch) in chars {
                let idx = match find_opt(defs, &ch.to_string()) {
                    Some(idx) => idx,
                    None => return Err(format!("Unrecognized option: '{}'", ch)),
                };
                names.push(idx);
                if defs[idx].hasarg != HasArg::No {
                    let next = j + ch.len_utf8();
                    if next < cur.len() {
                        i_arg = Some(cur[next..].to_string());
                    }
                    stop = true;
                }
                if stop {
                    break;
                }
            }
        }
        let n = names.len();
        for (pos, idx) in names.iter().enumerate() {
            match defs[*idx].hasarg {
                HasArg::No => {
                    if pos + 1 == n && i_arg.is_some() {
                        return Err(format!("Option '{}' does not take an argument", defs[*idx].name()));
                    }
                    vals[*idx].push(None);
                }
                HasArg::Maybe => {
                    let mut val = i_arg.take();
                    if val.is_none() && !was_long {
                        if i < args.len() && !is_arg(&args[i]) {
                            val = Some(args[i].clone());
                            i += 1;
                        }
                    }
                    vals[*idx].push(val);
                }
                HasArg::Yes => {
                    let val = match i_arg.take() {
                        Some(v) => v,
                        None => {
                            if i < args.len() {
                                let v = args[i].clone();
                                i += 1;
                                v
                            } else {
                                return Err(format!("Argument to option '{}' missing", defs[*idx].name()));
                            }
                        }
                    };
                    vals[*idx].push(Some(val));
                }
            }
        }
    }
    for (idx, d) in defs.iter().enumerate() {
        if d.occur == Occur::Optional && vals[idx].len() > 1 {
            return Err(format!("Option '{}' given more than once", d.name()));
        }
    }
    Ok(Matches { vals, free })
}

fn find_opt(defs: &[OptDef], name: &str) -> Option<usize> {
    if name.len() == 1 {
        let c = name.chars().next().unwrap();
        defs.iter().position(|d| d.short == Some(c))
    } else {
        defs.iter().position(|d| d.long == Some(name))
    }
}

fn usage(prog: &str) -> String {
    let brief = format!("Usage: {} [options] <path> [<path>..]", prog);
    let mut out = format!("{}\n\nOptions:\n", brief);
    for d in opt_defs().iter() {
        let mut row = String::from("    ");
        match d.short {
            Some(s) => {
                row.push('-');
                row.push(s);
                if d.long.is_some() {
                    row.push_str(", ");
                } else {
                    row.push(' ');
                }
            }
            None => {
                row.push_str("    ");
            }
        }
        if let Some(l) = d.long {
            row.push_str("--");
            row.push_str(l);
        }
        match d.hasarg {
            HasArg::No => {}
            HasArg::Yes => row.push_str(&format!(" {}", d.hint)),
            HasArg::Maybe => row.push_str(&format!(" [{}]", d.hint)),
        }
        let rowlen = row.chars().count();
        if rowlen < 24 {
            for _ in 0..24 - rowlen {
                row.push(' ');
            }
        } else {
            row.push_str("\n");
            row.push_str(&" ".repeat(24));
        }
        let desc_sep = format!("\n{}", " ".repeat(24));
        for word in d.desc.split_whitespace() {
            let wl = word.chars().count();
            let rl = row.chars().count();
            if rl + 1 + wl > 78 {
                row.push_str(&desc_sep);
                row.push_str(word);
            } else {
                if rl != 0 {
                    row.push(' ');
                }
                row.push_str(word);
            }
        }
        out.push_str(&row);
        out.push('\n');
    }
    out
}

