extern "C" {
    fn ioctl(fd: i32, request: u64, ...) -> i32;
}

#[repr(C)]
struct Winsize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

fn term_width() -> usize {
    let mut ws = Winsize { ws_row: 0, ws_col: 0, ws_xpixel: 0, ws_ypixel: 0 };
    let rc = unsafe { ioctl(1, 0x5413u64, &mut ws as *mut Winsize) };
    if rc == 0 && ws.ws_col > 0 {
        ws.ws_col as usize
    } else {
        80
    }
}

// ---------------------------------------------------------------- tree

#[derive(Clone, Copy, PartialEq)]
enum Kind {
    Dir,
    File,
    Link,
    Other,
}

struct Node {
    name: String,
    own: u64,
    total: u64,
    kind: Kind,
    link_ok: bool,
    exec: bool,
    ext: Option<String>,
    children: Vec<Node>,
    bar: usize,
    aggregated: bool,
}

impl Node {
    fn new(name: String, own: u64, kind: Kind) -> Node {
        Node {
            name,
            own,
            total: own,
            kind,
            link_ok: false,
            exec: false,
            ext: None,
            children: Vec::new(),
            bar: 0,
            aggregated: false,
        }
    }
}

struct Opts {
    depth: usize,
    aggr: u64,
    usage: bool,
    bytes: bool,
    files_only: bool,
    excludes: Vec<String>,
    no_hidden: bool,
    ascii: bool,
    colors: Colors,
    use_colors: bool,
}

fn list_dir(path: &Path, name: &str) -> Vec<fs::DirEntry> {
    match fs::read_dir(path) {
        Ok(rd) => rd.filter_map(|e| e.ok()).collect(),
        Err(e) => {
            eprintln!("Couldn't read {} ({:?})", name, e.kind());
            Vec::new()
        }
    }
}

fn scan(path: &Path, name: &str, depth: usize, o: &Opts, root: bool) -> Node {
    let md = fs::symlink_metadata(path);
    let (own, kind, exec, ext) = match md {
        Ok(m) => {
            let sz = if o.usage { m.blocks().saturating_mul(512) } else { m.len() };
            let ft = m.file_type();
            let k = if ft.is_dir() {
                Kind::Dir
            } else if ft.is_symlink() {
                Kind::Link
            } else if ft.is_file() {
                Kind::File
            } else {
                Kind::Other
            };
            let ex = m.mode() & 0o111 != 0;
            let ext = Path::new(name).extension().map(|e| e.to_string_lossy().to_string());
            (sz, k, ex, ext)
        }
        Err(_) => (0, Kind::File, false, None),
    };
    let mut node = Node::new(name.to_string(), own, kind);
    node.exec = exec;
    node.ext = ext;
    if kind == Kind::Link {
        node.link_ok = fs::metadata(path).is_ok();
    }
    if kind != Kind::Dir || o.files_only {
        if root && kind == Kind::Dir {
            // files-only root directory: no children
        }
        return node;
    }
    let entries = list_dir(path, name);
    if depth < o.depth {
        let _ = list_dir(path, name);
    }
    let mut children: Vec<Node> = Vec::new();
    for e in entries {
        let cname = e.file_name().to_string_lossy().to_string();
        if o.no_hidden && cname.starts_with('.') {
            continue;
        }
        if o.excludes.iter().any(|x| x == &cname) {
            continue;
        }
        let cpath = path.join(&cname);
        let child = scan(&cpath, &cname, depth + 1, o, false);
        children.push(child);
    }
    node.children = children;
    node.total = node.own + node.children.iter().map(|c| c.total).sum::<u64>();
    node
}

fn aggregate(node: &mut Node, o: &Opts) {
    if !node.children.is_empty() {
        for c in node.children.iter_mut() {
            aggregate(c, o);
        }
        let mut shown: Vec<Node> = Vec::new();
        let mut small: Vec<Node> = Vec::new();
        for c in node.children.drain(..) {
            if c.total < o.aggr {
                small.push(c);
            } else {
                shown.push(c);
            }
        }
        let sum: u64 = small.iter().map(|c| c.total).sum();
        shown.sort_by(|a, b| b.total.cmp(&a.total));
        if sum > 0 {
            let mut n = Node::new("<aggregated>".to_string(), sum, Kind::File);
            n.total = sum;
            n.aggregated = true;
            shown.push(n);
        }
        node.children = shown;
    }
}

fn assign_bars(node: &mut Node, parent_bar: usize, denom: u64) {
    if node.children.is_empty() {
        return;
    }
    for c in node.children.iter_mut() {
        let w = (c.total * parent_bar as u64) / denom;
        c.bar = if w == 0 { 0 } else { (w - 1) as usize };
    }
    for c in node.children.iter_mut() {
        assign_bars(c, c.bar, c.total.max(1));
    }
}

// ---------------------------------------------------------------- printing

fn fit(name: &str, avail: usize) -> (String, usize) {
    let mut w = 0usize;
    let mut out = String::new();
    for c in name.chars() {
        let cw = char_width(c);
        if w + cw > avail {
            return (out, avail);
        }
        out.push(c);
        w += cw;
    }
    (out, w)
}

fn bar_string(bars: &[usize], w: usize, fill: char, shades: &[char], ascii: bool) -> String {
    let mut s = String::new();
    let mut prev = 0usize;
    let d = bars.len();
    for (i, &b) in bars.iter().enumerate() {
        let start = w - b;
        if i + 1 < d {
            let shade = if ascii { '#' } else { shades[i] };
            s.push_str(&shade.to_string().repeat(start - prev));
        } else {
            if i > 0 {
                let shade = if ascii { '#' } else { shades[i - 1] };
                s.push_str(&shade.to_string().repeat(start - prev));
            } else {
                s.push_str(&" ".repeat(start - prev));
            }
            s.push_str(&fill.to_string().repeat(w - start));
        }
        prev = start;
    }
    s
}

fn color_for(node: &Node, colors: &Colors) -> Option<String> {
    if node.kind == Kind::Dir {
        return colors.get("di").cloned();
    }
    if node.kind == Kind::Link {
        if node.link_ok {
            return colors.get("ln").cloned();
        } else {
            return colors.get("or").cloned();
        }
    }
    if node.exec {
        return colors.get("ex").cloned();
    }
    if let Some(e) = &node.ext {
        if let Some(c) = colors.ext(e) {
            return Some(c.clone());
        }
    }
    if node.kind == Kind::File {
        return colors.get("fi").cloned();
    }
    colors.get("bd").cloned()
}

fn print_node(
    node: &Node,
    prefix: &str,
    ancestors: &[usize],
    name_w: usize,
    bar_w: usize,
    o: &Opts,
    parent_total: u64,
) {
    let prefix_w = str_width(prefix);
    if prefix_w >= name_w {
        return;
    }
    let avail = name_w - 1 - prefix_w;
    let (disp, dw) = fit(&node.name, avail);
    let pad = name_w - prefix_w - dw;
    let mut line = String::new();
    line.push_str(prefix);
    match color_for(node, &o.colors) {
        Some(c) if o.use_colors => {
            line.push_str(&format!("\x1b[{}m{}\x1b[0m", c, disp));
        }
        _ => line.push_str(&disp),
    }
    for _ in 0..pad {
        line.push(' ');
    }
    line.push('\u{2502}');
    line.push(' ');
    let mut bars: Vec<usize> = ancestors.to_vec();
    bars.push(node.bar);
    let fill = if o.ascii { '#' } else { '\u{2588}' };
    let shades = ['\u{2591}', '\u{2592}', '\u{2593}', '\u{2588}'];
    line.push_str(&bar_string(&bars, bar_w, fill, &shades, o.ascii));
    line.push('\u{2502}');
    let pct = (node.total * 100 / parent_total) as usize;
    line.push_str(&format!("{:>4}%", pct));
    let st = fmt_size(node.total, o.bytes);
    let sw = st.chars().count().max(14);
    line.push_str(&format!("{:>width$}", st, width = sw));
    println!("{}", line);
    let mut child_prefix = String::from(prefix);
    if node.children.is_empty() {
        return;
    }
    let last = node.children.len() - 1;
    for (i, c) in node.children.iter().enumerate() {
        let conn = if i == last { "└─ " } else { "├─ " };
        let mut ap: Vec<usize> = ancestors.to_vec();
        ap.push(node.bar);
        print_node(c, &format!("{}{}", child_prefix, conn), &ap, name_w, bar_w, o, node.total);
    }
    if last == 0 {
        child_prefix.push_str("   ");
    } else {
        child_prefix.push_str("│  ");
    }
    let _ = child_prefix;
}

pub fn run() {
    let argv: Vec<String> = env::args().collect();
    let prog = argv.get(0).cloned().unwrap_or_else(|| "dutree".to_string());
    let defs = opt_defs();
    let matches = match parse_args(&defs, &argv[1..]) {
        Ok(m) => m,
        Err(e) => {
            print!("{}", usage(&prog));
            flush();
            eprintln!("{}", e);
            std::process::exit(1);
        }
    };
    if matches.opt_present(9) {
        print!("{}", usage(&prog));
        flush();
        return;
    }
    if matches.opt_present(10) {
        println!("{}", VERSION);
        return;
    }
    let mut paths = matches.free.clone();
    if paths.is_empty() {
        paths.push(".".to_string());
    }
    for p in &paths {
        if !fs::metadata(p).is_ok() {
            eprintln!("path {} doesn't exist", p);
            flush();
            std::process::exit(1);
        }
    }
    let depth = match matches.opt_str(0) {
        Some(s) => s.parse::<usize>().unwrap_or(usize::MAX),
        None => usize::MAX,
    };
    let aggr_str = match matches.opt_str(1) {
        Some(s) => s.clone(),
        None => "1M".to_string(),
    };
    if matches.opt_present(2) {
        // summary: -d 1 -a 1M
    }
    let summary = matches.opt_present(2);
    let depth = if summary { 1 } else { depth };
    let aggr = if summary { parse_size("1M") } else { 0 };
    let _ = aggr_str;
    println!("placeholder");
}

fn flush() {
    let _ = std::io::stdout().flush();
}

fn parse_size(s: &str) -> u64 {
    let (num, mult) = split_size(s);
    let _ = (num, mult);
    0
}

fn split_size(s: &str) -> (&str, u64) {
