// ---------------------------------------------------------------- unicode width

fn char_width(c: char) -> usize {
    let cp = c as u32;
    if cp < 0x20 {
        return 0;
    }
    if cp < 0x7f {
        return 1;
    }
    if cp < 0xa0 {
        return 0;
    }
    if cp == 0xad {
        return 1;
    }
    if cp == 0x202f {
        return 1;
    }
    if is_zero_width(cp) {
        return 0;
    }
    if is_wide(cp) {
        return 2;
    }
    1
}

fn in_ranges(cp: u32, ranges: &[(u32, u32)]) -> bool {
    let mut lo = 0usize;
    let mut hi = ranges.len();
    while lo < hi {
        let mid = (lo + hi) / 2;
        let (a, b) = ranges[mid];
        if cp < a {
            hi = mid;
        } else if cp > b {
            lo = mid + 1;
        } else {
            return true;
        }
    }
    false
}

fn is_zero_width(cp: u32) -> bool {
    in_ranges(cp, ZERO_WIDTH)
}

fn is_wide(cp: u32) -> bool {
    in_ranges(cp, WIDE)
}

