// ---------------------------------------------------------------- size formatting

const UNITS: [&str; 7] = ["B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB"];

fn fmt_size(bytes: u64, bytes_mode: bool) -> String {
    if bytes_mode {
        return format!("{} B", bytes);
    }
    let mut v = bytes as f64;
    let mut i = 0usize;
    while v >= 1024.0 && i + 1 < UNITS.len() {
        v /= 1024.0;
        i += 1;
    }
    if i == 0 {
        format!("{} B", bytes)
    } else {
        format!("{:.2} {}", v, UNITS[i])
    }
}

// ---------------------------------------------------------------- LS_COLORS

pub struct Colors {
    types: HashMap<String, String>,
    exts: HashMap<String, String>,
}

impl Colors {
    fn get(&self, k: &str) -> Option<&String> {
        self.types.get(k)
    }
    fn ext(&self, e: &str) -> Option<&String> {
        self.exts.get(e)
    }
    fn empty(&self) -> bool {
        self.types.is_empty() && self.exts.is_empty()
    }
}

fn parse_ls_colors(s: &str) -> Colors {
    let mut types: HashMap<String, String> = HashMap::new();
    let mut exts: HashMap<String, String> = HashMap::new();
    for entry in s.split(':') {
        if entry.is_empty() {
            continue;
        }
        let mut it = entry.split('=');
        let key = it.next().unwrap();
        let val = it.next().unwrap();
        let (a, b) = key.split_at(2);
        if a == "*." {
            exts.insert(b.to_string(), val.to_string());
        } else {
            types.insert(key.to_string(), val.to_string());
        }
    }
    Colors { types, exts }
}

// ---------------------------------------------------------------- option parsing (getopts compatible)

#[derive(Clone, Copy, PartialEq)]
enum HasArg {
    No,
    Yes,
    Maybe,
}

#[derive(Clone, Copy, PartialEq)]
enum Occur {
    Optional,
    Multi,
}

struct OptDef {
    short: Option<char>,
    long: Option<&'static str>,
    hasarg: HasArg,
    occur: Occur,
    hint: &'static str,
    desc: &'static str,
}

impl OptDef {
    fn name(&self) -> String {
        match self.long {
            Some(l) => l.to_string(),
            None => self.short.unwrap().to_string(),
        }
    }
}

fn opt_defs() -> Vec<OptDef> {
    vec![
        OptDef { short: Some('d'), long: Some("depth"), hasarg: HasArg::Maybe, occur: Occur::Optional, hint: "[DEPTH]", desc: "show directories up to depth N (def 1)" },
        OptDef { short: Some('a'), long: Some("aggr"), hasarg: HasArg::Maybe, occur: Occur::Optional, hint: "[N[KMG]]", desc: "aggregate smaller than N B/KiB/MiB/GiB (def 1M)" },
        OptDef { short: Some('s'), long: Some("summary"), hasarg: HasArg::No, occur: Occur::Optional, hint: "", desc: "equivalent to -da, or -d1 -a1M" },
        OptDef { short: Some('u'), long: Some("usage"), hasarg: HasArg::No, occur: Occur::Optional, hint: "", desc: "report real disk usage instead of file size" },
        OptDef { short: Some('b'), long: Some("bytes"), hasarg: HasArg::No, occur: Occur::Optional, hint: "", desc: "print sizes in bytes" },
